import os
import torch


class Config:
    """
    Configuration for the Regularized High-Capacity Kinematic Network (RHC-KN).
    Centralizes all hyperparameters, paths, and constants.
    """

    # ==========================================
    # Paths & Directories
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_37"
    CACHE_DIR = os.path.join(WORKING_DIR, "cache")

    # Metadata files generated by the analysis step
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")

    # Model and Submission paths
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "best_model.pth")
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==========================================
    # Data Processing
    # ==========================================
    # Sliding Window Strategy
    WINDOW_SIZE = 64
    STRIDE_TRAIN = 32
    STRIDE_TEST = 32  # 50% overlap of 64

    # Class Definitions
    # Labels 1-20 are gestures. We assign 0 to Background.
    NUM_CLASSES = 21
    BACKGROUND_CLASS_ID = 0

    # Feature Extraction
    AUDIO_SR = 16000
    N_MFCC = 13

    NUM_JOINTS = 20
    # Features per joint: 3 (Position mm) + 3 (Velocity) + 3 (Acceleration)
    JOINTS_DIM = 9
    SKELETON_INPUT_DIM = NUM_JOINTS * JOINTS_DIM  # 180

    # Total Input Dimension (Skeleton + Audio)
    TOTAL_INPUT_DIM = SKELETON_INPUT_DIM + N_MFCC  # 193

    # ==========================================
    # Model Architecture (RHC-KN)
    # ==========================================
    # Stage 1: Encoder (Bi-GRU)
    HIDDEN_DIM = 128  # Per direction (Total hidden size = 256)
    DROPOUT_ENCODER = 0.5

    # Stage 2 & 3: TCN Refinement
    DROPOUT_TCN = 0.3
    TCN_KERNEL_SIZE = 3
    # Monotonically increasing dilation schedule
    TCN_DILATIONS = [1, 2, 4, 8, 16]

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    SEED = 42
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    BATCH_SIZE = 32
    NUM_EPOCHS = 50
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-4
    PATIENCE = 10  # Early stopping patience

    # Loss Function Configuration
    BACKGROUND_WEIGHT = 0.2
    # Weight for the log-space smoothing loss term
    SMOOTHING_LOSS_WEIGHT = 0.15
    # Truncation threshold for smoothing loss
    SMOOTHING_THRESHOLD = 1.0

    # ==========================================
    # Inference & Post-Processing
    # ==========================================
    # Minimum duration (in frames) to keep a gesture prediction
    MIN_GESTURE_DURATION = 5

    # ==========================================
    # Debugging / Development
    # ==========================================
    DEBUG = False
    DEBUG_SUBSET_SIZE = 20  # Number of samples to use when DEBUG is True

    @classmethod
    def setup(cls):
        """
        Creates necessary working directories.
        """
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.CACHE_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)

    @classmethod
    def set_debug(cls, debug_mode: bool):
        """
        Toggles debug mode, adjusting epochs and dataset usage for quick testing.
        """
        cls.DEBUG = debug_mode
        if debug_mode:
            print("(!) DEBUG MODE ACTIVATED: Reduced epochs and dataset size.")
            cls.NUM_EPOCHS = 2
            cls.BATCH_SIZE = 4
            # Subset size is handled in the data loader via cls.DEBUG_SUBSET_SIZE
